CREATE FUNCTION notenschnitt(
  p_sch_id INT
)
RETURNS NUMERIC
LANGUAGE sql
AS $$
  SELECT ROUND(AVG(note), 2)
  FROM noten
  WHERE sch_id = p_sch_id;
$$;

SELECT notenschnitt(1);
-- 1.50  (Anna: DBI 1, POS 2)

CREATE PROCEDURE note_eintragen(
  p_sch  INT,
  p_fach VARCHAR,
  p_note INT
)
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_note NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION
      'Note % ist ungültig', p_note;
  END IF;
  INSERT INTO noten
    VALUES (p_sch, p_fach, p_note);
END;
$$;

CALL note_eintragen(1, 'DBI', 1);
-- CALL

CALL note_eintragen(1, 'AM', 7);
-- ERROR:  Note 7 ist ungültig

SELECT note_eintragen(1, 'E', 2);
-- ERROR: ... is a procedure
-- HINT:  To call a procedure,
--        use CALL.

CREATE FUNCTION beurteilung(
  p_sch_id INT
)
RETURNS TEXT
LANGUAGE plpgsql
AS $$
DECLARE
  v_schnitt NUMERIC;
BEGIN
  SELECT AVG(note) INTO v_schnitt
  FROM noten WHERE sch_id = p_sch_id;

  IF v_schnitt IS NULL THEN
    RETURN 'keine Noten';
  ELSIF v_schnitt <= 1.5 THEN
    RETURN 'ausgezeichnet';
  ELSIF v_schnitt <= 2.0 THEN
    RETURN 'guter Erfolg';
  ELSE
    RETURN 'bestanden';
  END IF;
END;
$$;
